params.command:
$ErrorActionPreference='Stop'
$oc='C:\Users\Xxkan\local-ai-tools\opencode\package\bin\opencode.exe'
$d=Join-Path $env:TEMP 'opencode-ollama-config-smoke'
if(Test-Path $d){Remove-Item -Recurse -Force $d}
New-Item -ItemType Directory -Path $d | Out-Null
$config=@'
{
  "$schema": "https://opencode.ai/config.json",
  "model": "ollama/qwen2.5-coder:7b",
  "providers": {
    "ollama": {
      "settings": {
        "baseURL": "http://127.0.0.1:11434/v1"
      }
    }
  }
}
'@
Set-Content -Path (Join-Path $d 'opencode.json') -Value $config -Encoding UTF8
Push-Location $d
try {
  & $oc run --standalone --auto --model 'ollama/qwen2.5-coder:7b' --format default 'Return exactly LOCAL_AGENT_OK and do not edit files.' 2>&1
  Write-Output ('EXIT='+$LASTEXITCODE)
} finally { Pop-Location }
